import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function corrupt(file) {
  return Object.assign(new Error(`Corrupt ledger file: ${file}`), { code: 'ERR_CORRUPT_LEDGER' });
}

function validate(batch) {
  if (!batch || typeof batch !== 'object' || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) throw invalid();
  const entries = [];
  for (let i = 0; i < batch.entries.length; i++) {
    const entry = batch.entries[i];
    if (!entry || typeof entry !== 'object' || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) throw invalid();
    // Normalize -0 so in-memory results match their JSON round trip.
    entries.push({ key: entry.key, delta: entry.delta === 0 ? 0 : entry.delta });
  }
  return { id: batch.id, entries };
}

function sameEntries(a, b) {
  return a.length === b.length && a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

function isSnapshot(value) {
  return value !== null && typeof value === 'object' && Number.isSafeInteger(value.revision) && value.revision >= 0
    && value.balances !== null && typeof value.balances === 'object' && !Array.isArray(value.balances)
    && Array.isArray(value.receipts) && value.receipts.length === value.revision;
}

function isPending(value) {
  return value !== null && typeof value === 'object' && isSnapshot(value.ledger) && value.ledger.revision > 0
    && value.batch !== null && typeof value.batch === 'object' && typeof value.batch.id === 'string';
}

async function read(io, file, fallback, check) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return fallback; throw error; }
  const value = JSON.parse(text);
  if (!check(value)) throw corrupt(file);
  return value;
}

// Stage into `<name>.tmp`, then atomically replace `<name>.json`. A failed or partial
// staging write never touches the published file.
async function save(io, directory, name, value) {
  const staged = path.join(directory, `${name}.tmp`);
  await io.writeFile(staged, JSON.stringify(value));
  await io.rename(staged, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (!error || error.code !== 'ENOENT') throw error; }
}

function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) throw invalid();
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

// Reads durable state without modifying it. Returns the committed snapshot (including a
// prepared-but-unpublished transaction) and which recovery steps remain.
async function load(io, directory) {
  await io.mkdir(directory, { recursive: true });
  const ledgerFile = path.join(directory, 'ledger.json');
  const pendingFile = path.join(directory, 'pending.json');
  const ledger = await read(io, ledgerFile, { revision: 0, balances: {}, receipts: [] }, isSnapshot);
  const pending = await read(io, pendingFile, null, isPending);
  if (!pending) return { state: ledger, publish: false, cleanup: false };
  const target = pending.ledger;
  const last = target.receipts[target.receipts.length - 1];
  if (!last || last.id !== pending.batch.id) throw corrupt(pendingFile);
  if (ledger.revision === target.revision) {
    // Already published; only the recovery record remains.
    const published = ledger.receipts[ledger.receipts.length - 1];
    if (!published || published.id !== pending.batch.id) throw corrupt(pendingFile);
    return { state: ledger, publish: false, cleanup: true };
  }
  if (ledger.revision === target.revision - 1) return { state: target, publish: true, cleanup: true };
  throw corrupt(pendingFile);
}

async function finish(io, directory, loaded) {
  if (loaded.publish) await save(io, directory, 'ledger', loaded.state);
  if (loaded.cleanup) await removePending(io, directory);
  return loaded.state;
}

export async function recoverLedger(directory, options) {
  const { io = fs } = options ?? {};
  return finish(io, directory, await load(io, directory));
}

export async function commitBatch(directory, batch, options) {
  const { io = fs, checkpoint } = options ?? {};
  batch = validate(batch);
  const loaded = await load(io, directory);
  const state = loaded.state;
  const receipt = state.receipts.find(item => item.id === batch.id);
  if (receipt) {
    if (!Array.isArray(receipt.entries) || !sameEntries(receipt.entries, batch.entries)) {
      throw Object.assign(new Error('Batch ID already used'), { code: 'ERR_BATCH_CONFLICT' });
    }
    return finish(io, directory, loaded);
  }
  // Validate resulting balances before any durable change.
  const next = apply(state, batch);
  await finish(io, directory, loaded);
  // Write-ahead record: the full target snapshot, so recovery needs nothing else.
  await save(io, directory, 'pending', { batch, ledger: next });
  if (typeof checkpoint === 'function') await checkpoint('prepared');
  await save(io, directory, 'ledger', next);
  if (typeof checkpoint === 'function') await checkpoint('published');
  await removePending(io, directory);
  if (typeof checkpoint === 'function') await checkpoint('complete');
  return next;
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const a = { id: 'a', entries: [{ key: 'cash', delta: 5 }] };
const b = { id: 'b', entries: [{ key: 'cash', delta: -2 }, { key: 'bank', delta: 4 }] };
const expected = { revision: 2, balances: { cash: 3, bank: 4 }, receipts: [a, b] };

function faulty(failAt, partial) {
  let n = 0;
  const io = {};
  for (const m of ['mkdir', 'readFile', 'writeFile', 'rename', 'unlink']) {
    io[m] = async (...args) => {
      if (m !== 'mkdir' && m !== 'readFile' && n++ === failAt) {
        if (m === 'writeFile' && partial) await fs.writeFile(args[0], String(args[1]).slice(0, 7));
        throw Object.assign(new Error('boom ' + m), { code: 'EIO' });
      }
      return fs[m](...args);
    };
  }
  return io;
}

let cases = 0;
for (let failAt = 0; failAt < 12; failAt++) for (const partial of [false, true]) for (const recoverFirst of [false, true]) {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-'));
  await commitBatch(dir, a);
  try { await commitBatch(dir, b, { io: faulty(failAt, partial) }); } catch (e) { assert.equal(e.code, 'EIO'); }
  if (recoverFirst) { const s = await recoverLedger(dir); assert.equal(s.revision, s.receipts.length); }
  assert.deepEqual(await commitBatch(dir, b), expected);
  assert.deepEqual(await recoverLedger(dir), expected);
  assert.deepEqual((await fs.readdir(dir)).filter(f => f.endsWith('.json')), ['ledger.json']);
  await fs.rm(dir, { recursive: true }); cases++;
}
for (const phase of ['prepared', 'published', 'complete']) for (const recoverFirst of [false, true]) {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-'));
  await commitBatch(dir, a);
  const err = new Error('stop');
  await assert.rejects(commitBatch(dir, b, { checkpoint: async p => { if (p === phase) throw err; } }), e => e === err);
  if (recoverFirst) assert.deepEqual(await recoverLedger(dir), expected);
  else {
    // a different new batch must not lose b
    const c = { id: 'c', entries: [] };
    const s = await commitBatch(dir, c);
    assert.deepEqual(s, { ...expected, revision: 3, receipts: [a, b, c] });
    assert.deepEqual(await recoverLedger(dir), s);
  }
  await fs.rm(dir, { recursive: true }); cases++;
}
{
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-'));
  const phases = [];
  await commitBatch(dir, a, { checkpoint: async p => phases.push(p) });
  assert.deepEqual(phases, ['prepared', 'published', 'complete']);
  await assert.rejects(commitBatch(dir, { id: 'a', entries: [] }), { code: 'ERR_BATCH_CONFLICT' });
  await assert.rejects(commitBatch(dir, { id: 'x', entries: [{ key: 'cash', delta: Number.MAX_SAFE_INTEGER }] }), { code: 'ERR_INVALID_BATCH' });
  await assert.rejects(commitBatch(dir, { id: 'x', entries: [{ key: 'Cash', delta: 1 }] }), { code: 'ERR_INVALID_BATCH' });
  await assert.rejects(commitBatch(dir, { id: '', entries: [] }), { code: 'ERR_INVALID_BATCH' });
  await fs.writeFile(path.join(dir, 'pending.tmp'), '{garbage');
  assert.deepEqual(await recoverLedger(dir), { revision: 1, balances: { cash: 5 }, receipts: [a] });
  await fs.writeFile(path.join(dir, 'ledger.json'), '{bad');
  await assert.rejects(recoverLedger(dir), SyntaxError);
  await fs.rm(dir, { recursive: true }); cases++;
}
console.log('ok', cases);
